"use client";

import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

const Dialog = DialogPrimitive.Root;
const DialogTrigger = DialogPrimitive.Trigger;
const DialogPortal = DialogPrimitive.Portal;
const DialogClose = DialogPrimitive.Close;

const DialogOverlay = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    className={cn(
      "fixed inset-0 z-50 bg-black/60 backdrop-blur-sm",
      "data-[state=open]:animate-in data-[state=closed]:animate-out",
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className
    )}
    {...props}
  />
));
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName;

const DialogContent = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Content
      ref={ref}
      className={cn(
        "fixed left-1/2 top-1/2 z-50 -translate-x-1/2 -translate-y-1/2",
        "w-full max-w-md",
        "bg-[var(--cs-bg)]",
        "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
        "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
        "shadow-2xl",
        className
      )}
      {...props}
    >
      {children}
    </DialogPrimitive.Content>
  </DialogPortal>
));
DialogContent.displayName = DialogPrimitive.Content.displayName;

const DialogHeader = ({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex items-center justify-between px-4 py-2",
      "bg-[var(--cs-bg-secondary)]",
      "border-b-2 border-b-[var(--cs-border-dark)]",
      className
    )}
    {...props}
  >
    {children}
    <DialogClose className="cs-font-ui text-xs text-[var(--cs-text-dim)] hover:text-white ml-auto">
      ✕
    </DialogClose>
  </div>
);
DialogHeader.displayName = "DialogHeader";

const DialogTitle = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    className={cn(
      "cs-font-ui text-sm text-[var(--cs-text-title)] cs-text-shadow",
      className
    )}
    {...props}
  />
));
DialogTitle.displayName = DialogPrimitive.Title.displayName;

const DialogDescription = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    className={cn(
      "cs-font-ui text-xs text-[var(--cs-text-secondary)]",
      className
    )}
    {...props}
  />
));
DialogDescription.displayName = DialogPrimitive.Description.displayName;

const DialogBody = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn("p-4", className)} {...props} />
);

const DialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex items-center justify-end gap-2 px-4 py-2",
      "bg-[var(--cs-bg-secondary)]",
      "border-t-2 border-t-[var(--cs-border-dark)]",
      className
    )}
    {...props}
  />
);
DialogFooter.displayName = "DialogFooter";

export {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
  DialogClose,
};

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
